const $ = s => document.querySelector(s);
const variants = {A:['Atlas','Señaladores arriba; portada centrada y acción al pie.'], B:['Herbario','Señaladores laterales; página estrecha con lectura editorial.'], C:['Libro de campo','Señaladores abajo; acción antes de la ilustración, cerca de la lectura.']};
let variant = new URLSearchParams(location.search).get('variant') || 'A';
if (!variants[variant]) variant='A';
const sections=['Personaje','Juegos','Afinador','Logros'];
const games=[['Simón','Escuchá una secuencia y repetila en el piano.','piano'],['Instrumentos','Escuchá y descubrí qué instrumento está sonando.','guitar'],['Rhythm Tap','Seguí el pulso y practicá la lectura de ritmos.','drum'],['Defender','Protegé el árbol reconociendo notas y acordes.','tree']];
let state={section:'Personaje',game:0,achievement:'Medallas',progress:0,reduced:false};
const svg = (body,box='0 0 300 320') => `<svg viewBox="${box}" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">${body}</svg>`;
const leaf=(x,y,r=0)=>`<path transform="translate(${x} ${y}) rotate(${r})" d="M0 0Q-30-35 0-60Q29-34 0 0Z" fill="var(--moss)" stroke="var(--primary)" stroke-width="2"/><path transform="translate(${x} ${y}) rotate(${r})" d="M0-5V-48" stroke="var(--primary)" fill="none"/>`;
const branch=`<path d="M32 286Q74 220 69 144M67 209L39 179M70 180L102 145" fill="none" stroke="var(--primary)" stroke-width="3"/>${leaf(68,163,-20)}${leaf(53,202,-50)}${leaf(77,199,50)}`;
const character=svg(`<ellipse cx="152" cy="292" rx="65" ry="9" fill="var(--sage)"/><path d="M119 249L116 286Q128 296 138 286L141 251M165 251L165 286Q179 296 190 285L183 249" fill="var(--primary)" stroke="var(--text)" stroke-width="3"/><path d="M110 159Q90 182 83 235L106 242L125 192M188 159Q211 181 217 232L194 240L178 190" fill="var(--moss)" stroke="var(--primary)" stroke-width="3"/><path d="M113 155Q149 140 184 155L201 251Q151 278 100 250Z" fill="var(--sage)" stroke="var(--primary)" stroke-width="3"/><path d="M151 177L149 256M106 227L135 231M165 230L194 224" fill="none" stroke="var(--primary)" stroke-width="2"/><path d="M109 169L150 195L190 166L176 145H123Z" fill="var(--moss)" stroke="var(--primary)" stroke-width="2"/><path d="M105 126Q94 70 150 56Q205 66 199 127L181 155H122Z" fill="var(--primary)" stroke="var(--text)" stroke-width="3"/><path d="M121 108Q150 87 181 109L181 135Q154 161 123 137Z" fill="var(--background)" stroke="var(--text)" stroke-width="2"/><path d="M138 120V126M166 120V126M147 137Q153 141 158 136" stroke="var(--text)" stroke-width="3" stroke-linecap="round" fill="none"/><path d="M149 76Q132 43 155 25Q176 53 149 76Z" fill="var(--success)" stroke="var(--primary)" stroke-width="2"/><path d="M151 69Q171 35 192 43Q187 68 151 69" fill="var(--moss)" stroke="var(--primary)" stroke-width="2"/><path d="M136 186Q152 174 168 187L151 208Z" fill="var(--success)" stroke="var(--primary)" stroke-width="2"/>${branch}<g transform="translate(300 0) scale(-1 1)">${branch}</g>`);
function artwork(kind){
 const frame=`<path d="M25 280Q15 166 55 93Q150 26 249 94Q287 169 275 280Z" fill="var(--surfaceSelected)"/>`;
 if(kind==='piano')return svg(frame+`<path d="M56 155Q146 115 246 154L252 250H50Z" fill="var(--primary)"/><path d="M53 202H250V254H53Z" fill="var(--surface)" stroke="var(--primary)" stroke-width="3"/>`+[1,2,3,4,5,6].map(n=>`<path d="M${53+n*28} 203V252" stroke="var(--primary)" stroke-width="2"/>`).join('')+[0,1,3,4,5].map(n=>`<path d="M${72+n*28} 202h13v30h-13Z" fill="var(--text)"/>`).join('')+leaf(97,140,-30)+leaf(210,136,35));
 if(kind==='guitar')return svg(frame+`<g transform="rotate(22 150 170)"><path d="M137 131Q94 144 113 180Q72 215 112 252Q158 280 190 245Q217 208 174 178Q190 143 161 131Z" fill="var(--success)" stroke="var(--primary)" stroke-width="3"/><path d="M140 68H159V182H140Z" fill="var(--moss)" stroke="var(--primary)" stroke-width="3"/><circle cx="149" cy="196" r="19" fill="var(--primary)"/><path d="M129 229H169M146 78V231M152 78V231" stroke="var(--text)" stroke-width="2"/></g>`+leaf(67,244,-30));
 if(kind==='drum')return svg(frame+`<path d="M71 163L89 243Q150 275 216 242L230 163" fill="var(--warning)" stroke="var(--primary)" stroke-width="3"/><path d="M83 180L111 243L141 184L170 249L208 180" fill="none" stroke="var(--background)" stroke-width="4"/><ellipse cx="150" cy="164" rx="79" ry="28" fill="var(--background)" stroke="var(--primary)" stroke-width="3"/><path d="M86 89L195 160M219 87L119 159" stroke="var(--primary)" stroke-width="7" stroke-linecap="round"/>`+leaf(252,133,25));
 return svg(frame+`<path d="M143 160Q155 219 116 269H185Q161 223 172 151Z" fill="var(--success)" stroke="var(--primary)" stroke-width="3"/><path d="M148 207L111 172M165 216L201 178" stroke="var(--primary)" stroke-width="5"/><path d="M67 168Q35 130 74 111Q59 70 111 74Q151 34 178 69Q225 50 233 100Q279 118 247 155Q254 198 205 190Q176 217 147 190Q103 209 92 178Q75 183 67 168Z" fill="var(--moss)" stroke="var(--primary)" stroke-width="3"/>`+leaf(93,155,-25)+leaf(198,143,30));
}
$('.forest').innerHTML=svg(`<path fill="var(--sage)" d="M0 0H480V900H0Z"/><path d="M0 120Q120 18 230 100Q345 8 480 112V0H0Z" fill="var(--moss)"/><path d="M0 0L60 0Q30 280 59 480L24 900H0ZM480 0H432Q451 224 423 480L459 900H480Z" fill="var(--primary)"/><path d="M0 807Q110 741 240 816Q360 743 480 811V900H0" fill="var(--moss)"/>`+Array.from({length:12},(_,i)=>`<g transform="translate(${i%2?466:12} ${135+i*65}) scale(${i%2?-1:1} 1)">${leaf(0,0,-55)}${leaf(8,28,-90)}</g>`).join(''),'0 0 480 900');
const nav=$('.bookmarks'); sections.forEach(s=>{const b=document.createElement('button');b.textContent=s;b.onclick=()=>{state.section=s;render()};nav.append(b)});
function modal(title,body){$('#dialogContent').innerHTML=`<h2>${title}</h2>${body}`;$('#dialog').showModal()}
function render(animate=true){
 document.body.dataset.variant=variant;
 nav.querySelectorAll('button').forEach((b,i)=>{if(sections[i]===state.section)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});
 document.body.classList.toggle('reduced',state.reduced);
 const p=$('#page');p.className='';
 if(state.section==='Personaje'){p.classList.add('character-page');p.innerHTML=`<h1>Personaje</h1><div class="cover-art">${character}</div>`}
 if(state.section==='Juegos'){const [name,copy,art]=games[state.game];p.classList.add('game-page');p.innerHTML=`<p class="eyebrow">Juegos</p><h1>${name}</h1><div class="cover-art">${artwork(art)}</div><p class="section-copy">${copy}</p><button class="primary" id="play">Jugar</button>`;$('#play').onclick=()=>modal(name,`<p>La preparación del juego se abre desde aquí. En este estudio solo probamos la navegación.</p><button class="primary" id="returnGame">Simular fin de partida</button>`);}
 if(state.section==='Afinador'){p.innerHTML=`<p class="eyebrow">Escuchar y afinar</p><h1>Afinador</h1><div class="cover-art" style="max-height:180px;min-height:120px">${artwork('guitar')}</div><div class="choices"><button class="choice" data-mode="Libre">Libre<span>Explorá la afinación sin una secuencia fija.</span></button><button class="choice" data-mode="Guiado">Guiado<span>Recorré las cuerdas de tu guitarra.</span></button><button class="choice" disabled>Entrenamiento de oído<span>Próximamente</span></button></div>`;p.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>modal(b.dataset.mode,`<p>Este destino existe en Android. La maqueta no captura ni reproduce audio.</p>`))}
 if(state.section==='Logros'){p.innerHTML=`<h1>Logros</h1><div class="segmented">${['Medallas','Progreso'].map(v=>`<button data-ach="${v}" aria-pressed="${state.achievement===v}">${v}</button>`).join('')}</div>`;
  if(state.achievement==='Medallas')p.innerHTML+=`<div class="empty-note">${svg(`<path d="M104 184L92 264L150 238L208 264L196 184" fill="var(--sage)" stroke="var(--primary)" stroke-width="3"/><circle cx="150" cy="137" r="73" fill="var(--background)" stroke="var(--primary)" stroke-width="3"/>${leaf(151,170,0)}`,'0 0 300 300').replace('<svg ','<svg class="empty-art" ')}<h2>Un lugar para tus medallas</h2><p>La colección estará disponible cuando definamos los objetivos.</p></div>`;
  else p.innerHTML+=`<div class="empty-note"><h2>${games[state.progress][0]}</h2><p>Acá podrás consultar tus niveles y desbloqueos.</p><p>Este estudio no carga datos de tu perfil.</p></div>`;
  p.querySelectorAll('[data-ach]').forEach(b=>b.onclick=()=>{state.achievement=b.dataset.ach;render()});
 }
 const paged=state.section==='Juegos'||(state.section==='Logros'&&state.achievement==='Progreso');
 $('.pagination').hidden=!paged;const n=state.section==='Juegos'?state.game:state.progress;
 $('#index').textContent=`${n+1} de ${games.length}`;$('#prev').disabled=n===0;$('#next').disabled=n===games.length-1;
 if(animate){p.classList.remove('turn');void p.offsetWidth;p.classList.add('turn')}
 $('#variantLabel').textContent=`${variant} · ${variants[variant][0]}`;$('#variantDescription').textContent=variants[variant][1];
 $('#state').textContent=JSON.stringify({variant,...state},null,2);console.info('PROTOTIPO',JSON.stringify({variant,...state}));
}
document.addEventListener('click',e=>{if(e.target.id==='returnGame'){$('#dialog').close();render(false)}});
$('#prev').onclick=()=>{state[state.section==='Juegos'?'game':'progress']--;render()};$('#next').onclick=()=>{state[state.section==='Juegos'?'game':'progress']++;render()};
$('#index').onclick=()=>{modal('Índice',games.map((g,i)=>`<button data-jump="${i}" ${i===(state.section==='Juegos'?state.game:state.progress)?'aria-current="page"':''}>${i+1}. ${g[0]}${i===(state.section==='Juegos'?state.game:state.progress)?' · Actual':''}</button>`).join(''));document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{state[state.section==='Juegos'?'game':'progress']=Number(b.dataset.jump);$('#dialog').close();render()})};
$('#more').onclick=()=>{modal('Más',['Resultados','Prueba de voz','Datos y demostración'].map(t=>`<button data-extra="${t}">${t}</button>`).join(''));document.querySelectorAll('[data-extra]').forEach(b=>b.onclick=()=>{$('#dialogContent').innerHTML=`<h2>${b.dataset.extra}</h2><p>Acceso conservado. Su contenido queda fuera de este prototipo del menú.</p>`})};
$('#closeDialog').onclick=()=>$('#dialog').close();
function switchVariant(delta){const keys=Object.keys(variants);variant=keys[(keys.indexOf(variant)+delta+keys.length)%keys.length];const u=new URL(location);u.searchParams.set('variant',variant);history.replaceState(null,'',u);render(false)}
$('#variantPrev').onclick=()=>switchVariant(-1);$('#variantNext').onclick=()=>switchVariant(1);
document.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,[contenteditable=true]')||$('#dialog').open)return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();switchVariant(e.key==='ArrowLeft'?-1:1)}});
$('#restart').onclick=()=>{state={section:'Personaje',game:0,achievement:'Medallas',progress:0,reduced:state.reduced};render(false)};
$('#reduce').onchange=e=>{state.reduced=e.target.checked;render(false)};
fetch('/tokens.json').then(r=>r.json()).then(tokens=>{for(const [key,val]of Object.entries(tokens.color))document.documentElement.style.setProperty('--'+key,val);document.documentElement.style.setProperty('--touch',tokens.touch.preferredMinimumLogicalSize+'px');document.documentElement.style.setProperty('--radius',tokens.radius.large+'px');document.documentElement.style.setProperty('--space',tokens.spacing.base+'px');document.documentElement.style.setProperty('--enter',tokens.motion.cardEnterMs+'ms');document.documentElement.style.setProperty('--press',tokens.motion.pressMs+'ms');document.documentElement.dataset.tokens='ready'});
document.fonts.ready.then(()=>document.documentElement.dataset.fonts='ready');
const entryParams=new URLSearchParams(location.search);
if(entryParams.get('reduce')==='1'){state.reduced=true;document.querySelector('#reduce').checked=true}
if(sections.includes(entryParams.get('section')))state.section=entryParams.get('section');
if(state.section==='Juegos'&&entryParams.has('game'))state.game=Math.max(0,Math.min(games.length-1,Number(entryParams.get('game'))||0));
render(false);
